-- Updates the LIVE 'Prospector Drip - 4 Step' sequence row in place (same id),
-- so any prospect currently mid-sequence keeps their progress and simply
-- receives the new content on their next scheduled send. Run this once in
-- the Supabase SQL editor after deploying the lib/drip.js + lib/
-- prospectorEmailTemplate.js changes and the public/assets/img/email/*
-- assets in this branch.
update public.drip_sequences
set description = $desc$Multi-touch outreach sequence for cold prospects from the Prospector tool, diagnosing site issues and routing to the free website scan.$desc$,
    steps = $json$[{"step":1,"delay_days":0,"subject":"Quick question about {{company}}'s website","body":"<!DOCTYPE html>\n<html lang=\"en\" xmlns:v=\"urn:schemas-microsoft-com:vml\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<meta name=\"color-scheme\" content=\"light\">\n<meta name=\"supported-color-schemes\" content=\"light\">\n<title>Gobiya</title>\n<!--[if mso]>\n<noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript>\n<![endif]-->\n<link href=\"https://fonts.googleapis.com/css2?family=Open+Sans:wght@700;800&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  body, table, td { -webkit-text-size-adjust:100%; -ms-text-size-adjust:100%; }\n  table, td { mso-table-lspace:0pt; mso-table-rspace:0pt; }\n  img { border:0; line-height:100%; outline:none; text-decoration:none; -ms-interpolation-mode:bicubic; }\n  body { margin:0; padding:0; width:100% !important; background-color:#F5F6F8; }\n  a { color:#C4380C; }\n  .preheader { display:none !important; visibility:hidden; mso-hide:all; font-size:1px; line-height:1px; max-height:0; max-width:0; opacity:0; overflow:hidden; }\n  @media screen and (max-width:600px) {\n    .container { width:100% !important; }\n    .px-sm { padding-left:24px !important; padding-right:24px !important; }\n    .heading { font-size:22px !important; line-height:1.3 !important; }\n    .hero-img { height:auto !important; }\n  }\n</style>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F5F6F8;\">\n  <div class=\"preheader\">A free 60-second scan shows you exactly what's slowing {{company}} down.</div>\n  <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color:#F5F6F8;\">\n    <tr>\n      <td align=\"center\" style=\"padding:32px 16px;\">\n        <table role=\"presentation\" class=\"container\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:600px;max-width:600px;background-color:#FFFFFF;\">\n\n          <tr>\n            <td style=\"background-color:#0C1050;padding:20px 40px;\" class=\"px-sm\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                <tr>\n                  <td align=\"left\" valign=\"middle\">\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                      <tr>\n                        <td valign=\"middle\" style=\"padding-right:10px;\">\n                          <img src=\"https://www.gobiya.com/assets/img/email/logo-gobiya-red.png\" width=\"26\" height=\"26\" alt=\"\" style=\"display:block;\">\n                        </td>\n                        <td valign=\"middle\" style=\"font-family:'Open Sans',Arial,Helvetica,sans-serif;font-size:19px;font-weight:800;letter-spacing:0.5px;color:#FFFFFF;\">\n                          GOBIYA\n                        </td>\n                      </tr>\n                    </table>\n                  </td>\n                  <td align=\"right\" valign=\"middle\" style=\"font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#B9BEDA;\">\n                    Los Angeles Digital Marketing\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"line-height:0;font-size:0;\">\n              <img src=\"https://www.gobiya.com/assets/img/email/hero-tech-seo.jpg\" width=\"600\" height=\"336\" alt=\"A technical SEO consultant reviewing a website\" class=\"hero-img\" style=\"display:block;width:100%;height:auto;\">\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:32px 40px 0 40px;\" class=\"px-sm\">\n              <span style=\"font-family:Arial,Helvetica,sans-serif;font-size:12px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#C4380C;\">Free Website Check</span>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:10px 40px 0 40px;\" class=\"px-sm\">\n              <h1 class=\"heading\" style=\"margin:0;font-family:'Open Sans',Arial,Helvetica,sans-serif;font-size:26px;line-height:1.25;font-weight:800;color:#0C1050;\">Most site owners never check what's under the hood</h1>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:16px 40px 0 40px;font-family:'Inter',Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#2E3563;\" class=\"px-sm\">\n              \n        <p style=\"margin:0 0 14px 0;\">Hi {{contact_name}},</p>\n        <p style=\"margin:0 0 14px 0;\">I noticed {{company}} is active in {{location}} — and most business owners in {{industry}} never open their website's \"engine.\" They just assume it works.</p>\n        <p style=\"margin:0 0 14px 0;\">Under the hood, small technical issues quietly cost real customers: pages that load too slow, broken links, information Google can't find, or a site that ChatGPT and other AI tools skip over entirely.</p>\n        <p style=\"margin:0 0 0 0;\">We built a free tool that checks all of it in about a minute — speed, on-page SEO, security, and whether AI search engines can even find {{company}}. No forms first, just a quick report back.</p>\n      \n            </td>\n          </tr>\n\n          <tr>\n            <td align=\"center\" style=\"padding:28px 40px 8px 40px;\" class=\"px-sm\">\n              \n              <!--[if mso]>\n              <v:roundrect xmlns:v=\"urn:schemas-microsoft-com:vml\" href=\"{{offer_link}}\" style=\"height:50px;v-text-anchor:middle;width:280px;\" arcsize=\"4%\" strokecolor=\"#E1420F\" fillcolor=\"#E1420F\">\n              <w:anchorlock/>\n              <center style=\"color:#ffffff;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;\">Scan My Site Free</center>\n              </v:roundrect>\n              <![endif]-->\n              <!--[if !mso]><!-->\n              <a href=\"{{offer_link}}\" style=\"background-color:#E1420F;border-radius:2px;color:#ffffff;display:inline-block;font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:bold;line-height:50px;text-align:center;text-decoration:none;width:280px;-webkit-text-size-adjust:none;mso-hide:all;\">Scan My Site Free</a>\n              <!--<![endif]-->\n            </td>\n          </tr>\n\n          \n\n          \n          <tr>\n            <td style=\"padding:24px 40px 0 40px;font-family:'Inter',Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;color:#474D74;\" class=\"px-sm\">\n              — Steve<br>Gobiya Growth Team\n            </td>\n          </tr>\n\n          <tr><td style=\"padding:24px 40px 0 40px;\" class=\"px-sm\"></td></tr>\n\n          \n\n          <tr>\n            <td style=\"background-color:#0C1050;padding:28px 40px;\" class=\"px-sm\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                <tr>\n                  <td style=\"font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.7;color:#B9BEDA;\">\n                    <strong style=\"color:#FFFFFF;\">Gobiya</strong> — 14553 Delano St #315, Van Nuys, CA 91411<br>\n                    (323) 744-1338 &nbsp;|&nbsp; <a href=\"https://www.gobiya.com\" style=\"color:#FF7A4D;text-decoration:none;\">gobiya.com</a>\n                  </td>\n                </tr>\n                <tr>\n                  <td style=\"padding-top:16px;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#8A90B4;\">\n                    You're receiving this because {{company}} was identified as a potential fit for Gobiya's services.\n                    <a href=\"mailto:hello@gobiya.com?subject=Unsubscribe\" style=\"color:#B9BEDA;text-decoration:underline;\">Reply to unsubscribe</a>\n                    &nbsp;|&nbsp;\n                    <a href=\"https://www.gobiya.com/privacy\" style=\"color:#B9BEDA;text-decoration:none;\">Privacy Policy</a>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n"},{"step":2,"delay_days":2,"subject":"How slow is {{website}}, really?","body":"<!DOCTYPE html>\n<html lang=\"en\" xmlns:v=\"urn:schemas-microsoft-com:vml\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<meta name=\"color-scheme\" content=\"light\">\n<meta name=\"supported-color-schemes\" content=\"light\">\n<title>Gobiya</title>\n<!--[if mso]>\n<noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript>\n<![endif]-->\n<link href=\"https://fonts.googleapis.com/css2?family=Open+Sans:wght@700;800&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  body, table, td { -webkit-text-size-adjust:100%; -ms-text-size-adjust:100%; }\n  table, td { mso-table-lspace:0pt; mso-table-rspace:0pt; }\n  img { border:0; line-height:100%; outline:none; text-decoration:none; -ms-interpolation-mode:bicubic; }\n  body { margin:0; padding:0; width:100% !important; background-color:#F5F6F8; }\n  a { color:#C4380C; }\n  .preheader { display:none !important; visibility:hidden; mso-hide:all; font-size:1px; line-height:1px; max-height:0; max-width:0; opacity:0; overflow:hidden; }\n  @media screen and (max-width:600px) {\n    .container { width:100% !important; }\n    .px-sm { padding-left:24px !important; padding-right:24px !important; }\n    .heading { font-size:22px !important; line-height:1.3 !important; }\n    .hero-img { height:auto !important; }\n  }\n</style>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F5F6F8;\">\n  <div class=\"preheader\">Slow-loading pages lose visitors before they see what you offer.</div>\n  <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color:#F5F6F8;\">\n    <tr>\n      <td align=\"center\" style=\"padding:32px 16px;\">\n        <table role=\"presentation\" class=\"container\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:600px;max-width:600px;background-color:#FFFFFF;\">\n\n          <tr>\n            <td style=\"background-color:#0C1050;padding:20px 40px;\" class=\"px-sm\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                <tr>\n                  <td align=\"left\" valign=\"middle\">\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                      <tr>\n                        <td valign=\"middle\" style=\"padding-right:10px;\">\n                          <img src=\"https://www.gobiya.com/assets/img/email/logo-gobiya-red.png\" width=\"26\" height=\"26\" alt=\"\" style=\"display:block;\">\n                        </td>\n                        <td valign=\"middle\" style=\"font-family:'Open Sans',Arial,Helvetica,sans-serif;font-size:19px;font-weight:800;letter-spacing:0.5px;color:#FFFFFF;\">\n                          GOBIYA\n                        </td>\n                      </tr>\n                    </table>\n                  </td>\n                  <td align=\"right\" valign=\"middle\" style=\"font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#B9BEDA;\">\n                    Los Angeles Digital Marketing\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"line-height:0;font-size:0;\">\n              <img src=\"https://www.gobiya.com/assets/img/email/developer-dashboard-review.jpg\" width=\"600\" height=\"336\" alt=\"A developer reviewing website performance data on a dashboard\" class=\"hero-img\" style=\"display:block;width:100%;height:auto;\">\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:32px 40px 0 40px;\" class=\"px-sm\">\n              <span style=\"font-family:Arial,Helvetica,sans-serif;font-size:12px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#C4380C;\">Site Speed Check</span>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:10px 40px 0 40px;\" class=\"px-sm\">\n              <h1 class=\"heading\" style=\"margin:0;font-family:'Open Sans',Arial,Helvetica,sans-serif;font-size:26px;line-height:1.25;font-weight:800;color:#0C1050;\">How slow is {{website}}, really?</h1>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:16px 40px 0 40px;font-family:'Inter',Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#2E3563;\" class=\"px-sm\">\n              \n        <p style=\"margin:0 0 14px 0;\">Hi {{contact_name}},</p>\n        <p style=\"margin:0 0 14px 0;\">Here's a number worth knowing: most visitors decide whether to stay on a page within the first few seconds. If {{website}} takes too long to load, they're gone before they ever see what {{company}} offers — and Google notices the same slowdown.</p>\n        <p style=\"margin:0 0 14px 0;\">Core Web Vitals — Google's speed and stability scores — factor directly into how often your site shows up in search. A slow site doesn't just lose visitors. It loses rankings.</p>\n        <p style=\"margin:0 0 0 0;\">The free scan measures your load speed the same way Google does, and flags exactly what's dragging it down.</p>\n      \n            </td>\n          </tr>\n\n          <tr>\n            <td align=\"center\" style=\"padding:28px 40px 8px 40px;\" class=\"px-sm\">\n              \n              <!--[if mso]>\n              <v:roundrect xmlns:v=\"urn:schemas-microsoft-com:vml\" href=\"{{offer_link}}\" style=\"height:50px;v-text-anchor:middle;width:280px;\" arcsize=\"4%\" strokecolor=\"#E1420F\" fillcolor=\"#E1420F\">\n              <w:anchorlock/>\n              <center style=\"color:#ffffff;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;\">Check My Site Speed Free</center>\n              </v:roundrect>\n              <![endif]-->\n              <!--[if !mso]><!-->\n              <a href=\"{{offer_link}}\" style=\"background-color:#E1420F;border-radius:2px;color:#ffffff;display:inline-block;font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:bold;line-height:50px;text-align:center;text-decoration:none;width:280px;-webkit-text-size-adjust:none;mso-hide:all;\">Check My Site Speed Free</a>\n              <!--<![endif]-->\n            </td>\n          </tr>\n\n          \n\n          \n\n          <tr><td style=\"padding:24px 40px 0 40px;\" class=\"px-sm\"></td></tr>\n\n          \n\n          <tr>\n            <td style=\"background-color:#0C1050;padding:28px 40px;\" class=\"px-sm\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                <tr>\n                  <td style=\"font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.7;color:#B9BEDA;\">\n                    <strong style=\"color:#FFFFFF;\">Gobiya</strong> — 14553 Delano St #315, Van Nuys, CA 91411<br>\n                    (323) 744-1338 &nbsp;|&nbsp; <a href=\"https://www.gobiya.com\" style=\"color:#FF7A4D;text-decoration:none;\">gobiya.com</a>\n                  </td>\n                </tr>\n                <tr>\n                  <td style=\"padding-top:16px;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#8A90B4;\">\n                    You're receiving this because {{company}} was identified as a potential fit for Gobiya's services.\n                    <a href=\"mailto:hello@gobiya.com?subject=Unsubscribe\" style=\"color:#B9BEDA;text-decoration:underline;\">Reply to unsubscribe</a>\n                    &nbsp;|&nbsp;\n                    <a href=\"https://www.gobiya.com/privacy\" style=\"color:#B9BEDA;text-decoration:none;\">Privacy Policy</a>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n"},{"step":3,"delay_days":4,"subject":"Can ChatGPT even find {{company}}?","body":"<!DOCTYPE html>\n<html lang=\"en\" xmlns:v=\"urn:schemas-microsoft-com:vml\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<meta name=\"color-scheme\" content=\"light\">\n<meta name=\"supported-color-schemes\" content=\"light\">\n<title>Gobiya</title>\n<!--[if mso]>\n<noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript>\n<![endif]-->\n<link href=\"https://fonts.googleapis.com/css2?family=Open+Sans:wght@700;800&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  body, table, td { -webkit-text-size-adjust:100%; -ms-text-size-adjust:100%; }\n  table, td { mso-table-lspace:0pt; mso-table-rspace:0pt; }\n  img { border:0; line-height:100%; outline:none; text-decoration:none; -ms-interpolation-mode:bicubic; }\n  body { margin:0; padding:0; width:100% !important; background-color:#F5F6F8; }\n  a { color:#C4380C; }\n  .preheader { display:none !important; visibility:hidden; mso-hide:all; font-size:1px; line-height:1px; max-height:0; max-width:0; opacity:0; overflow:hidden; }\n  @media screen and (max-width:600px) {\n    .container { width:100% !important; }\n    .px-sm { padding-left:24px !important; padding-right:24px !important; }\n    .heading { font-size:22px !important; line-height:1.3 !important; }\n    .hero-img { height:auto !important; }\n  }\n</style>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F5F6F8;\">\n  <div class=\"preheader\">AI Overviews, ChatGPT, and Perplexity read sites differently than Google does.</div>\n  <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color:#F5F6F8;\">\n    <tr>\n      <td align=\"center\" style=\"padding:32px 16px;\">\n        <table role=\"presentation\" class=\"container\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:600px;max-width:600px;background-color:#FFFFFF;\">\n\n          <tr>\n            <td style=\"background-color:#0C1050;padding:20px 40px;\" class=\"px-sm\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                <tr>\n                  <td align=\"left\" valign=\"middle\">\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                      <tr>\n                        <td valign=\"middle\" style=\"padding-right:10px;\">\n                          <img src=\"https://www.gobiya.com/assets/img/email/logo-gobiya-red.png\" width=\"26\" height=\"26\" alt=\"\" style=\"display:block;\">\n                        </td>\n                        <td valign=\"middle\" style=\"font-family:'Open Sans',Arial,Helvetica,sans-serif;font-size:19px;font-weight:800;letter-spacing:0.5px;color:#FFFFFF;\">\n                          GOBIYA\n                        </td>\n                      </tr>\n                    </table>\n                  </td>\n                  <td align=\"right\" valign=\"middle\" style=\"font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#B9BEDA;\">\n                    Los Angeles Digital Marketing\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"line-height:0;font-size:0;\">\n              <img src=\"https://www.gobiya.com/assets/img/email/hero-analytics-man.jpg\" width=\"600\" height=\"336\" alt=\"A marketer analyzing AI search visibility data\" class=\"hero-img\" style=\"display:block;width:100%;height:auto;\">\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:32px 40px 0 40px;\" class=\"px-sm\">\n              <span style=\"font-family:Arial,Helvetica,sans-serif;font-size:12px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#C4380C;\">AI Visibility Check</span>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:10px 40px 0 40px;\" class=\"px-sm\">\n              <h1 class=\"heading\" style=\"margin:0;font-family:'Open Sans',Arial,Helvetica,sans-serif;font-size:26px;line-height:1.25;font-weight:800;color:#0C1050;\">Can ChatGPT even find {{company}}?</h1>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:16px 40px 0 40px;font-family:'Inter',Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#2E3563;\" class=\"px-sm\">\n              \n        <p style=\"margin:0 0 14px 0;\">Hi {{contact_name}},</p>\n        <p style=\"margin:0 0 14px 0;\">Search doesn't only mean Google anymore. More people in {{industry}} are asking ChatGPT, Perplexity, and Google's AI Overviews for recommendations before they ever type a traditional search.</p>\n        <p style=\"margin:0 0 14px 0;\">The problem: most websites were built for the old rules. If {{website}} is missing clear structured information or blocks AI crawlers without knowing it, {{company}} may be invisible in exactly the answers your future customers are reading.</p>\n        <p style=\"margin:0 0 0 0;\">The free scan checks your AI visibility alongside your traditional SEO, so you know whether ChatGPT and Google AI Overviews can actually find you.</p>\n      \n            </td>\n          </tr>\n\n          <tr>\n            <td align=\"center\" style=\"padding:28px 40px 8px 40px;\" class=\"px-sm\">\n              \n              <!--[if mso]>\n              <v:roundrect xmlns:v=\"urn:schemas-microsoft-com:vml\" href=\"{{offer_link}}\" style=\"height:50px;v-text-anchor:middle;width:280px;\" arcsize=\"4%\" strokecolor=\"#E1420F\" fillcolor=\"#E1420F\">\n              <w:anchorlock/>\n              <center style=\"color:#ffffff;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;\">See My AI Visibility Free</center>\n              </v:roundrect>\n              <![endif]-->\n              <!--[if !mso]><!-->\n              <a href=\"{{offer_link}}\" style=\"background-color:#E1420F;border-radius:2px;color:#ffffff;display:inline-block;font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:bold;line-height:50px;text-align:center;text-decoration:none;width:280px;-webkit-text-size-adjust:none;mso-hide:all;\">See My AI Visibility Free</a>\n              <!--<![endif]-->\n            </td>\n          </tr>\n\n          \n\n          \n\n          <tr><td style=\"padding:24px 40px 0 40px;\" class=\"px-sm\"></td></tr>\n\n          \n\n          <tr>\n            <td style=\"background-color:#0C1050;padding:28px 40px;\" class=\"px-sm\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                <tr>\n                  <td style=\"font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.7;color:#B9BEDA;\">\n                    <strong style=\"color:#FFFFFF;\">Gobiya</strong> — 14553 Delano St #315, Van Nuys, CA 91411<br>\n                    (323) 744-1338 &nbsp;|&nbsp; <a href=\"https://www.gobiya.com\" style=\"color:#FF7A4D;text-decoration:none;\">gobiya.com</a>\n                  </td>\n                </tr>\n                <tr>\n                  <td style=\"padding-top:16px;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#8A90B4;\">\n                    You're receiving this because {{company}} was identified as a potential fit for Gobiya's services.\n                    <a href=\"mailto:hello@gobiya.com?subject=Unsubscribe\" style=\"color:#B9BEDA;text-decoration:underline;\">Reply to unsubscribe</a>\n                    &nbsp;|&nbsp;\n                    <a href=\"https://www.gobiya.com/privacy\" style=\"color:#B9BEDA;text-decoration:none;\">Privacy Policy</a>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n"},{"step":4,"delay_days":7,"subject":"Last look: what's {{website}} missing?","body":"<!DOCTYPE html>\n<html lang=\"en\" xmlns:v=\"urn:schemas-microsoft-com:vml\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<meta http-equiv=\"X-UA-Compatible\" content=\"IE=edge\">\n<meta name=\"color-scheme\" content=\"light\">\n<meta name=\"supported-color-schemes\" content=\"light\">\n<title>Gobiya</title>\n<!--[if mso]>\n<noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript>\n<![endif]-->\n<link href=\"https://fonts.googleapis.com/css2?family=Open+Sans:wght@700;800&family=Inter:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  body, table, td { -webkit-text-size-adjust:100%; -ms-text-size-adjust:100%; }\n  table, td { mso-table-lspace:0pt; mso-table-rspace:0pt; }\n  img { border:0; line-height:100%; outline:none; text-decoration:none; -ms-interpolation-mode:bicubic; }\n  body { margin:0; padding:0; width:100% !important; background-color:#F5F6F8; }\n  a { color:#C4380C; }\n  .preheader { display:none !important; visibility:hidden; mso-hide:all; font-size:1px; line-height:1px; max-height:0; max-width:0; opacity:0; overflow:hidden; }\n  @media screen and (max-width:600px) {\n    .container { width:100% !important; }\n    .px-sm { padding-left:24px !important; padding-right:24px !important; }\n    .heading { font-size:22px !important; line-height:1.3 !important; }\n    .hero-img { height:auto !important; }\n  }\n</style>\n</head>\n<body style=\"margin:0;padding:0;background-color:#F5F6F8;\">\n  <div class=\"preheader\">Two ways to find out — a free scan, or five minutes with a real person.</div>\n  <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"background-color:#F5F6F8;\">\n    <tr>\n      <td align=\"center\" style=\"padding:32px 16px;\">\n        <table role=\"presentation\" class=\"container\" width=\"600\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\" style=\"width:600px;max-width:600px;background-color:#FFFFFF;\">\n\n          <tr>\n            <td style=\"background-color:#0C1050;padding:20px 40px;\" class=\"px-sm\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                <tr>\n                  <td align=\"left\" valign=\"middle\">\n                    <table role=\"presentation\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                      <tr>\n                        <td valign=\"middle\" style=\"padding-right:10px;\">\n                          <img src=\"https://www.gobiya.com/assets/img/email/logo-gobiya-red.png\" width=\"26\" height=\"26\" alt=\"\" style=\"display:block;\">\n                        </td>\n                        <td valign=\"middle\" style=\"font-family:'Open Sans',Arial,Helvetica,sans-serif;font-size:19px;font-weight:800;letter-spacing:0.5px;color:#FFFFFF;\">\n                          GOBIYA\n                        </td>\n                      </tr>\n                    </table>\n                  </td>\n                  <td align=\"right\" valign=\"middle\" style=\"font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#B9BEDA;\">\n                    Los Angeles Digital Marketing\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"line-height:0;font-size:0;\">\n              <img src=\"https://www.gobiya.com/assets/img/email/analytics-dashboard-review.jpg\" width=\"600\" height=\"336\" alt=\"An analytics dashboard showing improved website performance\" class=\"hero-img\" style=\"display:block;width:100%;height:auto;\">\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:32px 40px 0 40px;\" class=\"px-sm\">\n              <span style=\"font-family:Arial,Helvetica,sans-serif;font-size:12px;font-weight:700;letter-spacing:1px;text-transform:uppercase;color:#C4380C;\">Last Call</span>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:10px 40px 0 40px;\" class=\"px-sm\">\n              <h1 class=\"heading\" style=\"margin:0;font-family:'Open Sans',Arial,Helvetica,sans-serif;font-size:26px;line-height:1.25;font-weight:800;color:#0C1050;\">Last look: what's {{website}} missing?</h1>\n            </td>\n          </tr>\n\n          <tr>\n            <td style=\"padding:16px 40px 0 40px;font-family:'Inter',Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#2E3563;\" class=\"px-sm\">\n              \n        <p style=\"margin:0 0 14px 0;\">Hi {{contact_name}},</p>\n        <p style=\"margin:0 0 14px 0;\">This is my last note, so let's make it useful. Since 2009, we've helped more than 500 Los Angeles businesses fix exactly the kind of technical issues the free scan catches — slow load times, pages Google can't crawl, and sites AI search tools skip right past. Clients rate us 5.0 on Google and 5.0 on Clutch.</p>\n        <p style=\"margin:0 0 0 0;\">If {{company}}'s website has never been checked for speed, SEO, security, and AI visibility, the free scan takes about a minute and hands you a plain-language report — no sales call required. And if you'd rather just talk it through, we're happy to take a look at {{website}} together and tell you what we'd fix first.</p>\n      \n            </td>\n          </tr>\n\n          <tr>\n            <td align=\"center\" style=\"padding:28px 40px 8px 40px;\" class=\"px-sm\">\n              \n              <!--[if mso]>\n              <v:roundrect xmlns:v=\"urn:schemas-microsoft-com:vml\" href=\"{{offer_link}}\" style=\"height:50px;v-text-anchor:middle;width:280px;\" arcsize=\"4%\" strokecolor=\"#E1420F\" fillcolor=\"#E1420F\">\n              <w:anchorlock/>\n              <center style=\"color:#ffffff;font-family:Arial,sans-serif;font-size:16px;font-weight:bold;\">Scan My Site Free</center>\n              </v:roundrect>\n              <![endif]-->\n              <!--[if !mso]><!-->\n              <a href=\"{{offer_link}}\" style=\"background-color:#E1420F;border-radius:2px;color:#ffffff;display:inline-block;font-family:Arial,Helvetica,sans-serif;font-size:16px;font-weight:bold;line-height:50px;text-align:center;text-decoration:none;width:280px;-webkit-text-size-adjust:none;mso-hide:all;\">Scan My Site Free</a>\n              <!--<![endif]-->\n            </td>\n          </tr>\n\n          \n          <tr>\n            <td align=\"center\" style=\"padding:0 40px 8px 40px;font-family:Arial,Helvetica,sans-serif;font-size:13px;\" class=\"px-sm\">\n              <a href=\"{{site_url}}/contact\" style=\"color:#6B7192;text-decoration:underline;\">Or talk to a real person →</a>\n            </td>\n          </tr>\n\n          \n          <tr>\n            <td style=\"padding:24px 40px 0 40px;font-family:'Inter',Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;color:#474D74;\" class=\"px-sm\">\n              — Steve<br>Gobiya Growth Team\n            </td>\n          </tr>\n\n          <tr><td style=\"padding:24px 40px 0 40px;\" class=\"px-sm\"></td></tr>\n\n          \n        <tr>\n          <td style=\"padding:0 40px 8px 40px;\" class=\"px-sm\">\n            <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n              <tr>\n                <td align=\"center\" style=\"font-family:Arial,Helvetica,sans-serif;font-size:12px;color:#6B7192;padding:14px 0;border-top:1px solid #E4E7EE;\">\n                  <span style=\"color:#0C1050;font-weight:700;\">★★★★★ 5.0 on Google</span>\n                  &nbsp;&nbsp;|&nbsp;&nbsp;\n                  <span style=\"color:#0C1050;font-weight:700;\">★★★★★ 5.0 on Clutch</span>\n                  &nbsp;&nbsp;|&nbsp;&nbsp;\n                  500+ Los Angeles businesses since 2009\n                </td>\n              </tr>\n            </table>\n          </td>\n        </tr>\n\n          <tr>\n            <td style=\"background-color:#0C1050;padding:28px 40px;\" class=\"px-sm\">\n              <table role=\"presentation\" width=\"100%\" cellpadding=\"0\" cellspacing=\"0\" border=\"0\">\n                <tr>\n                  <td style=\"font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.7;color:#B9BEDA;\">\n                    <strong style=\"color:#FFFFFF;\">Gobiya</strong> — 14553 Delano St #315, Van Nuys, CA 91411<br>\n                    (323) 744-1338 &nbsp;|&nbsp; <a href=\"https://www.gobiya.com\" style=\"color:#FF7A4D;text-decoration:none;\">gobiya.com</a>\n                  </td>\n                </tr>\n                <tr>\n                  <td style=\"padding-top:16px;font-family:Arial,Helvetica,sans-serif;font-size:11px;color:#8A90B4;\">\n                    You're receiving this because {{company}} was identified as a potential fit for Gobiya's services.\n                    <a href=\"mailto:hello@gobiya.com?subject=Unsubscribe\" style=\"color:#B9BEDA;text-decoration:underline;\">Reply to unsubscribe</a>\n                    &nbsp;|&nbsp;\n                    <a href=\"https://www.gobiya.com/privacy\" style=\"color:#B9BEDA;text-decoration:none;\">Privacy Policy</a>\n                  </td>\n                </tr>\n              </table>\n            </td>\n          </tr>\n\n        </table>\n      </td>\n    </tr>\n  </table>\n</body>\n</html>\n"}]$json$::jsonb
where title = 'Prospector Drip - 4 Step';
